```ts
// src/slugify.ts
export function slugify(input: string): Result<string, SlugifyError> {
  if (input.trim() === "") {
    return err({ type: "EmptyInput" });
  }
  return ok(input.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""));
}
